WITH filtered AS (SELECT *, HOUR(event_time) event_time_hour, CASE WHEN page = '/cart' THEN 1 ELSE 0 END is_cart FROM web_events WHERE event_time >= TO_TIMESTAMP('2023-06-25 06:00:00') AND page IS NOT NULL) SELECT id, session_id, event_type, page, event_time, duration_sec, event_time_hour, is_cart, SUM(duration_sec) OVER w_running running_duration_sec, AVG(event_time_hour) OVER (ORDER BY duration_sec ASC, id ASC ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) event_time_hour_avg_3 FROM filtered WINDOW w_running AS (PARTITION BY page ORDER BY event_time ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
